import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls} from './pathways-views.js?v=20261110-en1';
import {quantumCurveSVG} from './quantum-plots.js?v=20261110-en1';
export {esc,num,table,notes,sources,readControls};
const val=x=>typeof x==='boolean'?(x?"Yes":"No"):typeof x==='number'?num(x):x==null?"Not provided":typeof x==='object'?JSON.stringify(x):String(x);
const labels={exchangeSides:"swap the upper and lower sides",fourfold:"Quadruple rotation reserved",inversion:"spatial inversion",chiral:"Geometry chirality",polar:"allows polar vector",Rx:"rotates around π of x",Rz:"rotates around π of z",T:"time reversal"};
const anchors=new Map(),clean=r=>{const c=structuredClone(r);delete c.learningEvidence;return c;};
export const controlsHTML=(m,v)=>baseControls({...m,fields:m.fields.map(f=>f.type==='number'&&!['sites','layers','cut'].includes(f.key)?{...f,step:'any'}:f)},v).replace(/(<label[^>]*>)([^<]*)(?=<(?:select|input))/g,'$1<span>$2</span>');
function project(p,yaw=35,pitch=24){const a=yaw*Math.PI/180,b=pitch*Math.PI/180;return [p[0]*Math.cos(a)-p[1]*Math.sin(a),p[2]*Math.cos(b)+(p[0]*Math.sin(a)+p[1]*Math.cos(a))*Math.sin(b)];}
export function geometrySVG(g,{yaw=35,pitch=24,points=g.points,title="original structure",ghost=null}={}){
 const combined=[...points,...(ghost||[])],q=combined.map(p=>project(p,yaw,pitch)),max=Math.max(1,...q.flat().map(Math.abs)),scale=145/max,xy=p=>{const a=project(p,yaw,pitch);return [270+a[0]*scale,190-a[1]*scale];};
 const palette=['#267764','#bf8142','#7266a8','#b85959'],unique=[...new Set(g.labels)],color=i=>palette[unique.indexOf(g.labels[i])%palette.length];
 return `<svg viewBox="0 0 540 410" role="img" aria-label="${esc(title)}"><text x="20" y="28">${esc(title)}</text>${ghost?ghost.map(p=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="8" fill="none" stroke="#a3afa8" stroke-width="2"/>`;}).join(''):''}${points.map((p,i)=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="7" fill="${color(i)}"><title>${esc(g.labels[i])} · ${p.map(num).join(', ')}</title></circle>`;}).join('')}${[[1,0,0],[0,1,0],[0,0,1]].map((p,i)=>{const [x,y]=project(p,yaw,pitch);return `<line x1="65" y1="345" x2="${65+38*x}" y2="${345-38*y}" stroke="#4f6559"/><text x="${65+48*x}" y="${345-48*y}">${['x','y','z'][i]}</text>`;}).join('')}<text x="20" y="395">${esc(unique.join(' / '))} · Drag the perspective slider below</text></svg>`;
}
function vectorSVG(title,a,b){const scale=90/Math.max(1,...a.map(Math.abs),...b.map(Math.abs));const coords=v=>{const q=project(v);return[135+scale*q[0],120-scale*q[1]];};return `<svg viewBox="0 0 270 260" role="img" aria-label="${esc(title)}before and after transformation"><text x="20" y="25">${esc(title)}</text><path d="M30 120H240M135 45V205" stroke="#d4dfd6"/>${[a,b].map((v,i)=>{const [x,y]=coords(v);return `<line x1="135" y1="120" x2="${x}" y2="${y}" stroke="${i?'#b87631':'#267764'}" stroke-width="${i?3:5}"/><circle cx="${x}" cy="${y}" r="5" fill="${i?'#b87631':'#267764'}"/>`;}).join('')}<text x="15" y="230">Green: Original vector Gold: After transformation</text></svg>`;}
const matrix=m=>table(m[0].map((_,i)=>"No. "+(i+1)+" column"),m.map(row=>row.map(num)));
export function resultHTML(module,r){
 const inverse=r.inverseSetup;
 return `<div class="cn-summary">${table(["The result of this time","Numeric/Diagnostic"],r.summary.map(s=>[s.label,val(s.value)]))}</div><section class="ct-panel"><h3>3D demonstration of structure and operation</h3><div class="ft-pair"><div id="ft-geometry"></div><div id="ft-transformed"></div></div><div class="cn-audit-controls"><label>azimuth<input type="range" id="ft-yaw" min="0" max="360" value="35"></label><label>elevation angle<input type="range" id="ft-pitch" min="-70" max="70" value="24"></label></div><p>${module==='chirality'?"Left: original configuration; right: point set after optimal positive rotation registration of the mirror image, the gray circle is the original configuration. The element correspondence is stored in the complete JSON.":"The gray circle is the original configuration, and the selected spatial operation can be applied on the right side; the surface map repeatedly displays 3×3 in-plane primitive cell . The spin chain diagram only illustrates the site arrangement."}</p></section>
 <section class="ct-panel"><h3>Real space—momentum space—spin linkage</h3><p>Select the operations provided by this model to transform position, wavevector and axis vector spin respectively. Below is an independent vector demonstration; does not replace the symmetry check of the full model above.</p><label>space operation<select id="ft-operation" aria-label="space operation">${r.operations.map((o,i)=>`<option value="${i}">${i+1} · ${esc(o.name||('det(R)='+o.determinant+(o.flipsNormal?" · Swap both sides":'')))}</option>`).join('')}</select></label><label>overlay time reversal<select id="ft-time" aria-label="overlay time reversal"><option value="no">No</option><option value="yes">Yes</option></select></label><details><summary>adjusts three input vectors</summary><div class="ft-vectors">${[['position',"position r",[.3,.2,.1]],['momentum',"wavevector k (rad/length)",[.4,.3,.2]],['spin',"Spin S",[.2,.4,.7]]].map(([key,title,v])=>`<fieldset><legend>${title}</legend>${v.map((x,i)=>`<label>${['x','y','z'][i]}<input id="ft-${key}-${i}" type="number" min="-10" max="10" step="any" value="${x}"></label>`).join('')}</fieldset>`).join('')}</div></details><div id="ft-matrix"></div><button id="ft-link" type="button" class="secondary">application operation and linkage</button><div id="ft-linked-result" role="status"></div></section>
 ${r.pseudo?`<section class="ct-panel"><h3>tolerance and pseudosymmetry evidence</h3><p>candidates are from the unperturbed parent configuration; each item is checked for maximum displacement by fixed atomic correspondence. Currently accepting collections${r.pseudo.closed?"passed":"failed"}closure check.</p>${table(["operation serial number","Maximum mapping distance","Current tolerance accepted"],r.pseudo.residuals.map(a=>[a.index+1,num(a.maximum),val(a.accepted)]))}<p>The operands and approximate candidates for the strict current configuration are listed at the top.</p></section>`:''}
 ${r.spectrum?`<section class="ct-panel"><h3>Protection conditions and quantum states</h3>${table(["Operation","Hamiltonian relative residual","This value remains"],Object.entries(r.spectrum.symmetry).map(([k,v])=>[labels[k],num(v),v<1e-8?"Yes":"No"]))}<p>${esc(r.spectrum.stateSelection)}</p><p>eigenstate residual:${num(r.spectrum.stateResidual)}</p><h4>AKLT Virtual spin of fixed point</h4><div class="ft-pair">${matrix(r.virtual.Ux)}${matrix(r.virtual.Uz)}</div><p>${esc(r.virtual.explanation)} Current${r.virtual.available?"is at the AKLT point, and the analytical exchange phase is −1":"is a perturbation dynamic and does not output the virtual projective category."}。</p></section>`:''}
 ${r.optical?`<section class="ct-panel"><h3>independent round-trip polarization experiment</h3><p>The rotation angle comes from the teaching parameters you specified and is not fitted by the current structure. Fixed laboratory x/y axis, return travel using${r.optical.model==='natural'?"reverse rotation":"rotate in the same direction"}。</p><div class="ft-pair"><div><h4>outbound matrix</h4>${matrix(r.optical.forward)}</div><div><h4>round trip total matrix</h4>${matrix(r.optical.roundTrip)}</div></div><p>input x-line polarized output:${r.optical.output.map(num).join(', ')}</p></section>`:''}
 ${r.plots.map(p=>`<section class="ct-panel"><h3>${esc(p.title)}</h3>${quantumCurveSVG(p.series,{xLabel:p.xLabel,yLabel:p.yLabel})}</section>`).join('')}
 <section class="ct-panel"><h3>Disturbance path tracking</h3><p>Check parameters, symmetry and diagnostics point by point; only listed sampling points are counted on this page.</p><label>Path sampling point<input id="ft-path" type="range" min="0" max="${r.path.length-1}" value="0" step="1"></label><div id="ft-path-result"></div><button id="ft-load-path" type="button" class="secondary">Load this waypoint into the main experiment</button></section>
 <section class="ct-panel"><h3>Derivation and operation playback</h3><label>View steps<input id="ft-frame" type="range" min="0" max="${r.replay.length-1}" value="0" step="1"></label><div id="ft-frame-result"></div></section>
 <section class="ct-panel"><h3>Inverse symmetry identification</h3><p>Select unknown samples, add one test at a time, and check all remaining possible candidates. The answer does not need to be unique; it is only judged within the candidate set of this question.</p><label>unknown sample<select id="ft-sample">${inverse.candidates.map((c,i)=>`<option value="${c.id}">sample ${i+1}</option>`).join('')}</select></label><label>Next inspection<select id="ft-measure">${inverse.measurements.map(k=>`<option value="${k}">${labels[k]||k}</option>`).join('')}</select></label><button id="ft-observe" type="button" class="secondary">Obtain evidence for this check</button><div id="ft-observations" role="status">and all candidates need to be retained.</div><fieldset><legend>is still a possible candidate (multiple choices available)</legend>${inverse.candidates.map(c=>`<label class="ft-check"><input type="checkbox" data-ft-candidate="${c.id}" checked> ${esc(c.title)}</label>`).join('')}</fieldset><button id="ft-inverse-grade" type="button" class="secondary">Check candidate set</button><div id="ft-inverse-result" role="status"></div></section>
 <section class="ct-panel"><h3>formula and applicable conditions</h3>${r.formulas.map(f=>`<div class="obs-formula">${esc(f)}</div>`).join('')}${notes(r.assumptions)}</section>
 <section class="ct-panel"><h3>Paired experiments and research evidence</h3><button id="ft-pin" type="button" class="secondary">Fixed this result as A</button><button id="ft-compare" type="button" class="secondary">Compare current B and save</button><button id="ft-clear" type="button" class="secondary">Clear A</button><label>Comparative explanation<textarea id="ft-explanation" rows="3" maxlength="6000"></textarea></label><div id="ft-comparison" role="status"></div></section>`;
}
export function bindResult(module,r,root,{runLinked,runInverse,input,isCurrent,onEvidence}){
 const $=s=>root.querySelector(s);let active=true,linkTicket=0,inverseTicket=0,revealed=[];
 const valid=()=>active&&isCurrent();
 const selected=()=>r.operations[Number($('#ft-operation').value)];
 function drawGeometry(){if(!valid())return;const opt={yaw:Number($('#ft-yaw').value),pitch:Number($('#ft-pitch').value)},o=selected();$('#ft-geometry').innerHTML=geometrySVG(r.geometry,opt);const points=module==='chirality'?r.geometry.aligned:r.geometry.points.map(p=>o.matrix.map((row,i)=>row.reduce((s,v,j)=>s+v*p[j],o.translation[i])));$('#ft-transformed').innerHTML=geometrySVG(r.geometry,{...opt,points,ghost:r.geometry.points,title:module==='chirality'?"mirror optimal positive rotation registration":"Structure after selected space operation"});$('#ft-matrix').innerHTML=matrix(o.matrix)+`<p>translation t:${o.translation.map(num).join(', ')}</p>`;}
 $('#ft-yaw').oninput=drawGeometry;$('#ft-pitch').oninput=drawGeometry;drawGeometry();
 const clearLinked=()=>{linkTicket++;onEvidence('linked',null);$('#ft-linked-result').textContent="The vector or operation has changed, please apply the operation.";$('#ft-link').disabled=false;};
 $('#ft-operation').onchange=()=>{clearLinked();drawGeometry();};$('#ft-time').onchange=clearLinked;
 for(const key of ['position','momentum','spin'])for(let i=0;i<3;i++)$('#ft-'+key+'-'+i).oninput=clearLinked;
 $('#ft-link').onclick=async()=>{if(!valid())return;const id=++linkTicket,o=selected(),payload={matrix:o.matrix,translation:o.translation,timeReversal:$('#ft-time').value==='yes'};for(const key of ['position','momentum','spin'])payload[key]=[0,1,2].map(i=>($('#ft-'+key+'-'+i).value.trim()===''?NaN:Number($('#ft-'+key+'-'+i).value)));$('#ft-link').disabled=true;try{if(['position','momentum','spin'].some(key=>payload[key].some(x=>!Number.isFinite(x))))throw new Error("Please completely fill in the finite values ​​of the three vectors.");const answer=await runLinked(payload);if(!valid()||id!==linkTicket)return;$('#ft-linked-result').innerHTML=`<div class="ft-vectors">${vectorSVG("real space position",payload.position,answer.real)}${vectorSVG("Wavevector",payload.momentum,answer.momentum)}${vectorSVG("spin (axis vector)",payload.spin,answer.spin)}</div>`+table(["object","before transformation","after transformation"],[['r',payload.position.map(num).join(', '),answer.real.map(num).join(', ')],['k',payload.momentum.map(num).join(', '),answer.momentum.map(num).join(', ')],['S',payload.spin.map(num).join(', '),answer.spin.map(num).join(', ')]] )+`<p>${esc(answer.convention)}</p><p>translation phase (real part, imaginary part):${answer.phase.map(num).join(', ')}</p>`;onEvidence('linked',{input:payload,result:answer});}catch(e){if(valid()&&id===linkTicket)$('#ft-linked-result').textContent=e.message;}finally{if(valid()&&id===linkTicket)$('#ft-link').disabled=false;}};
 const frame=()=>{if(!valid())return;const f=r.replay[Number($('#ft-frame').value)];$('#ft-frame-result').innerHTML=`<h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>`;};$('#ft-frame').oninput=frame;frame();
 const path=()=>{if(!valid())return;const p=r.path[Number($('#ft-path').value)];const plain=Object.entries(p).filter(([k])=>k!=='symmetry'&&k!=='energies');$('#ft-path-result').innerHTML=table(["Diagnosis","value"],plain.map(([k,v])=>[{parameter:"parameter value",order:"reserved operands",closed:"closed",normalFlips:"Swap operands on both sides",accepted:"tolerance acceptance number",groundMultiplicity:"Ground state space dimension",firstSpacing:"Minimum two-level spacing",gapAboveGroundSpace:"energy gap above ground state space"}[k]||k,val(v)]))+(p.symmetry?table(["protection operation","relative residual error","value retention"],Object.entries(p.symmetry).map(([k,v])=>[labels[k],num(v),v<1e-8?"Yes":"No"])):'');onEvidence('path',{index:Number($('#ft-path').value),point:structuredClone(p),input:structuredClone(input)});};$('#ft-path').oninput=path;path();
 $('#ft-load-path').onclick=()=>{if(!valid())return;const value=r.path[Number($('#ft-path').value)].parameter,key=module==='layers'?'registry':module==='chirality'?'tolerance':input.pathAxis,el=$('#pw-'+key);el.value=String(value);$('#pw-form').oninput({target:el});$('#pw-form').onsubmit({preventDefault(){}});};
 const inverseInvalidate=()=>{inverseTicket++;$('#ft-observe').disabled=false;$('#ft-inverse-grade').disabled=false;$('#ft-inverse-result').textContent="The selection has changed, please check again.";onEvidence('inverse',null);};
 $('#ft-sample').onchange=()=>{revealed=[];inverseInvalidate();$('#ft-observations').textContent="; retain all candidates and identify them one by one.";root.querySelectorAll('[data-ft-candidate]').forEach(c=>c.checked=true);};
 root.querySelectorAll('[data-ft-candidate]').forEach(c=>c.onchange=inverseInvalidate);
 async function inspect(grade){if(!valid())return;const id=++inverseTicket;if(!grade&&!revealed.includes($('#ft-measure').value))revealed.push($('#ft-measure').value);const payload={domain:r.inverseDomain,target:$('#ft-sample').value,revealed:[...revealed],guesses:[...root.querySelectorAll('[data-ft-candidate]')].filter(c=>c.checked).map(c=>c.dataset.ftCandidate),grade};$('#ft-observe').disabled=true;$('#ft-inverse-grade').disabled=true;try{const answer=await runInverse(payload);if(!valid()||id!==inverseTicket)return;$('#ft-observations').innerHTML=table(["Inspection Obtained","results"],Object.entries(answer.observations).map(([k,v])=>[labels[k],val(v)]))+`<p>${answer.nextMeasurement?"suggests the next item:"+esc(labels[answer.nextMeasurement]):answer.unique?"The available evidence is sufficient to distinguish among the candidates in this question.":"The remaining available tests do not uniquely distinguish candidates."}</p>`;$('#ft-inverse-result').textContent=grade?(answer.correct?"✓ The candidate set is correct;":"candidate set needs to be corrected;")+"is still compatible with:"+answer.remaining.map(k=>answer.candidates.find(c=>c.id===k).title).join('、'):"The evidence has been updated, please reselect a candidate that is still a possible candidate.";onEvidence('inverse',grade?{input:payload,result:answer}:null);}catch(e){if(valid()&&id===inverseTicket)$('#ft-inverse-result').textContent=e.message;}finally{if(valid()&&id===inverseTicket){$('#ft-observe').disabled=false;$('#ft-inverse-grade').disabled=false;}}}
 $('#ft-observe').onclick=()=>inspect(false);$('#ft-inverse-grade').onclick=()=>inspect(true);
 const status=()=>{$('#ft-comparison').textContent=anchors.has(module)?"A has been fixed; comparison can be made after modifying the parameters and calculating B.":"A has not been fixed yet.";};status();
 $('#ft-pin').onclick=()=>{if(!valid())return;anchors.set(module,{input:structuredClone(input),result:clean(r),created:new Date().toISOString()});onEvidence('comparison',null);status();};
 $('#ft-clear').onclick=()=>{anchors.delete(module);onEvidence('comparison',null);status();};
 $('#ft-explanation').oninput=()=>{onEvidence('comparison',null);$('#ft-comparison').textContent="The explanation has been modified, please save the comparison again.";};
 $('#ft-compare').onclick=()=>{if(!valid())return;const A=anchors.get(module);if(!A){status();return;}const B={input:structuredClone(input),result:clean(r),created:new Date().toISOString()},explanation=$('#ft-explanation').value;onEvidence('comparison',{A,B,explanation});$('#ft-comparison').innerHTML=table(["quantity",'A','B'],r.summary.map(s=>[s.label,val(A.result.summary.find(x=>x.label===s.label)?.value),val(s.value)]))+"<p>The complete input, results and explanations are attached to this calculation and can be exported or included in the material project.</p>";};
 return()=>{active=false;linkTicket++;inverseTicket++;};
}
